begin;
create sequence if not exists public.commerce_product_ids start 8;
alter table public.commerce_products alter column id set default nextval('public.commerce_product_ids')::text;
alter table public.commerce_products add column if not exists base_cents integer not null default 3000;
alter table public.commerce_products add column if not exists markup_type text not null default 'percent' check(markup_type in ('percent','fixed'));
alter table public.commerce_products add column if not exists markup_value numeric not null default 0 check(markup_value>=0);
alter table public.commerce_products add column if not exists details jsonb not null default '{}';
update public.commerce_products set price_cents=3000,base_cents=3000 where product_type='human-cookie';
update public.commerce_products set base_cents=800 where id='6';
update public.commerce_products set details=jsonb_build_object('category',case when id='6' then 'Dog Treats' else 'Cookies' end,'subcategory',case when id in ('0','1','4') then 'Classics' when id in ('2','3') then 'Chocolate Lovers' when id='5' then 'Seasonal' else 'Sandie’s Treats' end,'collection',case when id='5' then 'Seasonal' else 'Everyday' end,'featured',true,'defaultImage','/brand/generated-v1/'||case id when '0' then 'classic' when '1' then 'oat' when '2' then 'crinkle' when '3' then 'macadamia' when '4' then 'cinnamon-kiss' when '5' then 'pumpkin' else 'sandies-treats' end||'.png','description',case id when '0' then 'A soft, buttery chocolate chip cookie filled with melted semi sweet chocolate and a golden-browned base.' when '1' then 'A soft, cinnamon-kissed oatmeal cookie with sweet raisins.' when '2' then 'A rich, brownie-like chocolate cookie with a delicate powdered sugar crackle and fudgy center.' when '3' then 'A soft, buttery cookie filled with creamy white chocolate and crunchy macadamia nuts.' when '4' then 'A soft, buttery snickerdoodle rolled in cinnamon sugar and baked with a tender, chewy center.' when '5' then 'A soft pumpkin cookie with warm autumn spice and generous pockets of semi sweet chocolate chips.' else 'Homemade pumpkin + peanut butter dog treats made with simple, natural ingredients.' end) where details='{}';
insert into public.commerce_products(id,slug,title,price_cents,base_cents,package_count,product_type,details) values('7','peanut-butter-bliss','Peanut Butter Bliss',3000,3000,12,'human-cookie','{"category":"Cookies","subcategory":"Chocolate Lovers","collection":"Everyday","featured":true,"description":"A homemade peanut butter and chocolate cookie, baked fresh in small batches.","defaultImage":"/brand/logo.png"}') on conflict(id) do nothing;
create table if not exists public.commerce_admins(user_id uuid primary key references auth.users(id));
create table if not exists public.commerce_addresses(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),address jsonb not null,created_at timestamptz not null default now());
create table if not exists public.commerce_carts(owner_key text primary key,items jsonb not null default '[]',updated_at timestamptz not null default now());
create table if not exists public.commerce_reviews(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),display_name text not null,rating integer not null check(rating between 1 and 5),body text not null,status text not null default 'pending' check(status in ('pending','approved','rejected')),created_at timestamptz not null default now());
create table if not exists public.commerce_newsletter(email text primary key,status text not null default 'pending' check(status in ('pending','subscribed','unsubscribed')),token_hash text not null,requested_at timestamptz not null default now(),confirmed_at timestamptz,consent_text text not null);
create table if not exists public.commerce_audit(id uuid primary key default gen_random_uuid(),actor_id uuid not null references auth.users(id),action text not null,record_id text,created_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['commerce_admins','commerce_addresses','commerce_carts','commerce_reviews','commerce_newsletter','commerce_audit'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon,authenticated',t); execute format('grant all on public.%I to service_role',t); end loop; end $$;
grant usage,select on sequence public.commerce_product_ids to service_role;
insert into public.commerce_settings(key,value) values('public_site','{"contactEmail":"admin@cookiesandchips.com","socials":[{"platform":"instagram","handle":"@cook.ies_and_chips","url":"https://www.instagram.com/cook.ies_and_chips/","visible":true}],"monthlyProductId":"5","storyIntro":"Cookies & Chips is inspired by my daughter Ali. Her memory is at the heart of everything I bake. I believe something as simple as a warm cookie can bring a little comfort, even if only for a minute.","storyBody":"My daughter Ali passed away from cancer at age 10. Her memory is at the heart of Cookies & Chips and everything I make.\n\nThe idea grew from a simple belief: sometimes a warm cookie or a little chocolate can make a hard moment feel better, even if only for a minute.\n\nFrom my home kitchen, I bake thick, soft, gooey cookies in small batches, with quality ingredients and lots of love. The name keeps things simple and centered on what I love to bake most: cookies.\n\nWhether you are sharing a box with family, sending a little thank-you, or treating yourself, I hope these cookies bring a small moment of comfort and happiness.\n\nWith love,\nHeather","cancellationPolicy":"Orders may be canceled for a full refund at least 48 hours before the scheduled pickup or delivery date. Email admin@cookiesandchips.com with your order number to request a cancellation.","allergenNotice":"Products are made in a home kitchen that may come in contact with common food allergens, including wheat, eggs, milk, peanuts, and other allergens. Cookies & Chips cannot guarantee an allergen-free environment. Please review the ingredient list for any allergies or sensitivities before serving."}') on conflict(key) do nothing;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('product-images','product-images',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
commit;
